// Package prompts is the prompt library: ready-made questions about a
// person's own training, sleep and recovery, written for an AI assistant that
// reads the data through the MCP server. It is the one source for three
// outputs: the prompts the MCP server lists (prompts/list, prompts/get), the
// page docs/learn/prompts.md and the agent skill skills/open-health-sync.
// The last two are generated by ./internal/prompts/cmd/genprompts, and a test
// fails when a committed copy drifts.
package prompts

import (
	"fmt"
	"regexp"
	"strings"
)

// Arg is one blank of a prompt.
type Arg struct {
	// Name is the MCP argument name, written {name} in Prompt.Text.
	Name string
	// Description tells the client what to fill in.
	Description string
	// Placeholder is what the docs page shows in place of the blank, in
	// brackets: an example or the default.
	Placeholder string
	// Default fills an optional blank left empty. An Arg with no Default is
	// required.
	Default string
}

// Required reports whether the blank must be filled.
func (a Arg) Required() bool { return a.Default == "" }

// Prompt is one question of the library.
type Prompt struct {
	// Name is the MCP prompt name.
	Name string
	// Title is the short name the docs page and clients show.
	Title string
	// When says in one line what the prompt is for.
	When string
	// Section groups the prompts on the docs page.
	Section string
	// Text is the question, with {arg} blanks. Line breaks are for the docs
	// page; MCP clients receive it as one paragraph.
	Text string
	Args []Arg
}

// Sections lists the docs page sections in order.
var Sections = []string{"Every day", "Every week", "Before an event", "Coming back", "Your data itself"}

