var blank = regexp.MustCompile(`\{([a-z_]+)\}`)

// Find returns the prompt named name.
func Find(name string) (Prompt, bool) {
	for _, p := range Library {
		if p.Name == name {
			return p, true
		}
	}
	return Prompt{}, false
}

// Fill returns the prompt text with its blanks filled from values, defaults
// for optional ones left empty, as one paragraph. A required blank left empty
// is an error.
func (p Prompt) Fill(values map[string]string) (string, error) {
	vals := map[string]string{}
	for _, a := range p.Args {
		v := strings.TrimSpace(values[a.Name])
		if v == "" {
			v = a.Default
		}
		if v == "" {
			return "", fmt.Errorf("argument %q is required: %s", a.Name, a.Description)
		}
		vals[a.Name] = v
	}
	text := blank.ReplaceAllStringFunc(p.Text, func(m string) string { return vals[m[1:len(m)-1]] })
	return strings.Join(strings.Fields(text), " "), nil
}

// DocText returns the prompt text as the docs page shows it: line breaks
// kept, each blank as its [placeholder].
func (p Prompt) DocText() string {
	return blank.ReplaceAllStringFunc(p.Text, func(m string) string {
		for _, a := range p.Args {
			if a.Name == m[1:len(m)-1] {
				return "[" + a.Placeholder + "]"
			}
		}
		return m
	})
}
